"""Register the explicitly authorized Badge extension and its exact sources."""
from pathlib import Path
import copy,hashlib,json,runpy,shutil
ROOT=Path(__file__).resolve().parents[2]
BASE='evidence/badge-pilot/'
def read(p):return json.loads((ROOT/p).read_text())
def ref(p):return dict(path=p,sha256=hashlib.sha256((ROOT/p).read_bytes()).hexdigest())
def save(p,v):
 p=ROOT/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def split(p):
 text=(ROOT/p).read_text();a,b=text[4:].split('\n---\n',1);return json.loads(a),b
def contract(p,m,b):(ROOT/p).write_text('---\n'+json.dumps(m,ensure_ascii=False,indent=2)+'\n---\n'+b)
def adopt():
 if (ROOT/'norms/components/badge.1.1.0.md').exists():raise ValueError('Already adopted; use selected owners, do not run adoption twice')
 paths=['norms/components/badge.1.0.0.md','norms/components/input.2.0.0.md','norms/tokens/blueheart.6.0.0.json','norms/catalog.json','governance/policy.json','governance/decisions.json']
 paths += ['consumption/'+f+'/'+p for f in ['badge','input'] for p in ['manifest.json','current-build-plan.json','current-native-ledger.json','binding-map.csv','variable-map.csv','token-minimum.json']]
 entries=[]
 for p in paths:
  dest=BASE+'history/'+p.removeprefix('consumption/').removeprefix('norms/components/').removeprefix('norms/tokens/')
  (ROOT/dest).parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(ROOT/p,ROOT/dest);entries.append(dict(original=p,archive=dest,sha256=ref(p)['sha256']))
 save(BASE+'history/manifest.json',dict(role='IMMUTABLE_PREVIOUS_CUT',entries=entries))
 plan=runpy.run_path(str(ROOT/'implementations/figma/badge-plan.py'))['analyze']()
 auth=ref('evidence/authorization/badge-full-request.txt')
 policy=read('governance/policy.json');policy['component_content']='REGISTERED_FAMILIES_WITH_FULL_BADGE';policy['figma_access']='SOURCE_READ_ONLY_DESTINATION_REGISTERED_FAMILIES_SCOPED_WRITE';save('governance/policy.json',policy)
 decisions=read('governance/decisions.json');decisions['decisions'].append(dict(id='ADR-025',status='ADOPTED',actor='implementing_agent',statement='El encargo humano sustituye el alcance temporal de Badge por las 18 combinaciones reales de seis tipos y tres tamaños en la página Badge de Blue Heart DS. La elección humana conserva warning y documenta su contraste insuficiente. Se amplía el único set compartido en su identidad existente: la variante subtle/small, Label, doce variables y sus keys se conservan; los consumidores de Input heredan el componente completo sin swaps destructivos. La receta observada requiere 35 firmas (23 adiciones), con colores invariantes, solo tres colecciones, aliases semánticos existentes y scopes de propiedad separados. Se adoptan Badge 1.1.0, Input 2.0.1 por pin compatible y BLUEHEART-TOKENS 6.1.0 aditivo. La anatomía usa iconos Phosphor vinculados y opcionales; icono y Label comparten semántico conforme BH-P06. Se conservan geometría, tipografía, contenido y ausencia de interacciones. La referencia y el proyecto original siguen en solo lectura; React/Graphify y releases oficiales no se habilitan. No acredita revisión humana independiente.',scope=['BADGE-001','INPUT-001','BLUEHEART-TOKENS','full-badge-figma','component-reverse-dependency-audit'],source=auth));save('governance/decisions.json',decisions)
 ts=read(BASE+'history/blueheart.6.0.0.json');ts['version']='6.1.0';known={t['id']for t in ts['tokens']};ts['tokens'] += [{k:v for k,v in t.items()if k not in ['figmaName','web','themeBehavior']}for t in plan['tokens']if t['id']not in known];save('norms/tokens/blueheart.6.1.0.json',ts)
 sources=[dict(id='SRC-USER',**auth),dict(id='SRC-IDENTITY',**ref(BASE+'source/identity.json'))]
 for name in ['small','medium','large','variables-and-notes','variables-remaining','examples','example-icons']:sources.append(dict(id='SRC-'+name.upper().replace('-','_'),**ref(BASE+'source/'+name+'.json')))
 old,b=split(BASE+'history/badge.1.0.0.md')
 m={k:copy.deepcopy(v)for k,v in old.items()if k not in ['dependencies','sources','requirements']};m.update(version='1.1.0',authority=dict(kind='DELEGATED',decision_id='ADR-025'),sources=sources,profile_data=dict(anatomy=['container','Left icon (optional Phosphor instance)','Label','Right icon (optional Phosphor instance)'],composition='fixed-with-optional-instance-swaps',accessibility='defined-with-warning-contrast-exception'))
 m['dependencies']=[dict(kind='token',id=t['id'],relation='uses')for t in plan['tokens']]
 sections={
 'REQ-SCOPE':'Badge 1.1.0 sustituye el alcance temporal subtle/small con la familia completa observada en el set raíz 1234:65377, página 1234:53606. Un único set Badge reutilizable en Blue Heart DS contiene las 18 combinaciones; no sustituye Dot ni representa un botón. El proyecto original y Figma raíz permanecen en solo lectura. La receta derivada se consulta en consumption/badge/current-build-plan.json; el MD es la única autoridad de diseño/función.',
 'REQ-API':'type = neutral | subtle | info | success | warning | error; size = small | medium | large. Label TEXT editable, inicialmente Label. Show left icon y Show right icon BOOLEAN independientes, false por defecto; Left icon y Right icon INSTANCE_SWAP de Phosphor. Anatomy: Left icon → Label → Right icon. Sin Slots arbitrarios. No hay eje state, hover, focus, pressed, selected ni disabled; no crear variantes o tokens para ellos. Para compatibilidad se conserva el default existente subtle/small; las 18 combinaciones quedan disponibles. La raíz parte de neutral/large, diferencia explícita limitada al valor inicial del set local, sin alterar la apariencia de ninguna variante.',
 'REQ-GEOMETRY':'Auto Layout horizontal HUG en ambos ejes, alineación vertical CENTER y horizontal MIN. Radio 4, gap 4, strokeAlign INSIDE y strokesIncludedInLayout=false. Small: padding 0 vertical /8 horizontal, Label 12/20, iconos 12; altura natural 20. Medium: padding 4/8, Label 12/16, iconos 16; altura natural y maxHeight 24. Large: padding 4/12, Label 14/24, iconos 16; altura natural y maxHeight 32. Conservar estas diferencias reales aunque la descripción raíz sugiera otra talla de icono. Solo subtle tiene borde de 1 px. Los anchos 46 (small/medium) y 59 (large) corresponden al ejemplo Label sin iconos, no son anchos fijos. Ancho HUG con texto o iconos visibles; sin truncado ni saltos automáticos. El contenedor host resuelve etiquetas que no caben sin escalar Badge ni recortarlo.',
 'REQ-TYPOGRAPHY':'Manrope Regular, tracking 0 PIXELS, sin escalar tipografía. Los tres roles small/medium/large mantienen sus tamaños y line-heights observados de REQ-GEOMETRY mediante estilos compartidos con variables. El estilo existente badge/subtle-small mantiene su ID y se reutiliza para todos los small por tener la misma firma tipográfica; crear solo badge/label-medium y badge/label-large. Cada texto conserva textStyleId y los bindings de familia, estilo, tamaño, line-height y tracking.',
 'REQ-THEME':'Todos los roles de Badge son INVARIANT y repiten su alias semántico en Contable, Administrativo, Servicios y Personas. Neutral y subtle son metadatos: ambos texto/icono primary; neutral fondo surface sin borde, solo para superficie de color; subtle fondo neutro tenue con borde. Info, success, warning y error expresan información, éxito, atención y fallo mediante sus semánticos existentes; no cambiar con tema de producto ni crear modos por tipo. Valores y aliases completos pertenecen al token set seleccionado, no a una paleta independiente en este MD. Se conserva warning de la raíz por elección humana; su excepción es local a Badge.',
 'REQ-TOKENS':'Aplicar BH-P07 seleccionado. 360 usos fuente se agrupan en 35 firmas únicas: conservar las 12 variables existentes y añadir solo 23. No retirar IDs ni cambiar APIs existentes. Un color distinto por función usa la firma necesaria; neutral/subtle comparten texto e icono, y los scopes TEXT_FILL/SHAPE_FILL siguen separados aunque su alias sea igual. Gap y padding vertical de 4 comparten spacing/compact; ambos iconos comparten ancho/alto por talla. La altura HUG no requiere height-small: medium/large vinculan únicamente el maxHeight observado. Tres colecciones primitive, semantic, component; grupo badge; sin nuevos primitivos o semánticos. La tabla siguiente fija las rutas Figma y el nombre CSS explícito permanece en el token set.',
 'REQ-CONSUMERS':'Input consume exclusivamente subtle/small para códigos ISO de moneda (por ejemplo MXN/USD); mantener Label editable, Badge anidado expuesto e inicialmente oculto, y su pin exacto a BADGE-001@1.1.0. La ampliación se hace sobre el set y la variante existentes, de modo que el uso temporal pasa a la familia compartida sin borrar ni desacoplar instancias. Auditar todas las páginas y verificar los 113 usos previos en Input y los tres ejemplos previos de Badge; conservar IDs de instancias, texto, visibilidad, vínculo, geometría y overrides legítimos. Tab consume Dot; no cambiar sus contadores. No dejar un segundo Badge privado o un set temporal paralelo. La auditoría inversa y mapa de migración conservan el corte anterior como historia.',
 'REQ-ICONS':'Consumir BH-P06: Phosphor del equipo en Figma y paquete oficial en desarrollo cuando se implemente. Default fuente Presentation, Format=Outline /Weight=Fill, key 3f0d7ae9a02577d4fb4e615737d09fa1b49ec230. Es un placeholder intercambiable de la raíz, no una regla para comunicar estados. Ejemplos observados: CheckCircle Light, WarningCircle Light e Info Light. Iconos opcionales decorativos siempre siguen el Label correspondiente mediante el mismo vector de aliases semánticos, con token propio SHAPE_FILL y binding WIDTH_HEIGHT. No copiar paths locales ni modificar el maestro remoto. Probar ambos lados visibles, cuatro modos y sustituciones desde instancias; no usar el icono derecho como acción de cerrar.',
 'REQ-CONTENT':'Etiqueta breve y no interactiva para estado o atributo. Success: proceso concluido; warning: atención sin bloquear; error: fallo o estado negativo; info: en curso/informativo; subtle/neutral: metadatos. El mismo estado conserva tipo entre productos. Small para tablas/listas densas; medium estándar; large para encabezado de detalle. Un tamaño por lista/tabla. Sentence case, idealmente 1–3 palabras y hasta 20 caracteres; son recomendaciones editoriales, no un máximo del API. No truncar; abreviar o delegar una notificación al host si no cabe, sin construir otra familia aquí. Usar concordancia, término fiscal correcto, fechas día-mes y moneda ISO; no incluir montos ni datos personales/fiscales sensibles. No apilar varios estados en un mismo objeto ni convertir Badge en botón/chip removible.',
 'REQ-A11Y':'El texto describe el estado; color e icono no son el único medio. Sin foco, interacción ni reacciones de prototipo. En web futura los iconos son decorativos aria-hidden y el host aporta contexto y aria-live cuando cambie un estado en tiempo real. La fuente reconoce warning alrededor de 3:1, inferior a 4.5:1 para texto pequeño; la elección humana conserva esos colores. Registrar cálculo desde los valores reales, no redondear a cumplimiento AA. Las demás mediciones se documentan como contraste de color, sin certificar accesibilidad funcional web desde Figma. El host mantiene texto claro y puede reforzar warning crítico con icono izquierdo.',
 'REQ-QA':'Comprobar 18 variantes, propiedades, ausencia de estados inventados, tres estilos aplicados, tipografía y geometría contra fuente con tolerancia numérica 0.01 px y colores 1e-6. Identidades, aliases, scopes, WEB y nombres exigen igualdad exacta. Desde instancias cubrir 18×4 temas×4 combinaciones de iconos (ninguno/izquierdo/derecho/ambos), texto corto/largo, swaps Phosphor conservando color y tamaño, y los consumidores de Input con Show badge activado. Validar invariancia y contraste incluyendo la excepción warning. Infraestructura/check no acreditan QA visual ni revisión independiente; declarar estas evidencias por separado.'}
 m['requirements']=[dict(id=k,force='MUST',provenance='DERIVED'if k in ['REQ-TOKENS','REQ-CONSUMERS','REQ-ICONS','REQ-QA']else'EXPLICIT',sources=['SRC-USER','SRC-IDENTITY','SRC-SMALL','SRC-MEDIUM','SRC-LARGE'],acceptance=[v.split('. ')[0]+'.'])for k,v in sections.items()]
 body='# BADGE-001 · Badge 1.1.0\n\n'
 for k,v in sections.items():
  body+='### '+k+'\n\n'+v+'\n\n'
  if k=='REQ-TOKENS':body+='| ID lógico | Ruta Figma |\n|---|---|\n'+''.join('| '+t['id']+' | '+t['figmaName']+' |\n'for t in plan['tokens'])+'\n'
 contract('norms/components/badge.1.1.0.md',m,body)
 inp,body=split(BASE+'history/input.2.0.0.md');inp.update(version='2.0.1',authority=dict(kind='DELEGATED',decision_id='ADR-025'));inp['sources'].append(dict(id='SRC-BADGE-FULL',**auth))
 for d in inp['dependencies']:
  if d['kind']=='contract'and d['id']=='BADGE-001':d['version']='1.1.0'
 inp['requirements'].append(dict(id='REQ-BADGE-FULL',force='MUST',provenance='EXPLICIT',sources=['SRC-BADGE-FULL'],acceptance=['Consumir Badge 1.1.0 subtle/small en las mismas instancias, conservando contenido, visibilidad, geometría, identidad y Show badge; sin helper temporal.']))
 body=body.replace('Input 2.0.0','Input 2.0.1').replace('BADGE-001@1.0.0','BADGE-001@1.1.0')+'\n### REQ-BADGE-FULL\n\nConsumir el Badge completo BADGE-001@1.1.0 por composición. Input sigue usando solo subtle/small con Label de moneda; los nuevos iconos del Badge permanecen ocultos por defecto. La ampliación del principal existente elimina el alcance temporal y conserva todos los usos actuales sin sustituir IDs ni alterar la API de Input. La receta y el ledger actuales fijan el componente compartido; QA del encargo verifica los 113 usos y la reproducción de Show badge desde cada combinación de Input. No crear un helper privado ni otro grupo de tokens en Input para Badge.\n'
 contract('norms/components/input.2.0.1.md',inp,body)
 c=read('norms/catalog.json')
 for e in c['contracts']:
  if e['id']in ['BADGE-001','INPUT-001']:
   version='1.1.0'if e['id']=='BADGE-001'else'2.0.1';e.update(version=version,**ref('norms/components/'+('badge'if e['id']=='BADGE-001'else'input')+'.'+version+'.md'))
 for e in c['token_sets']:
  if e['current']:e.update(version='6.1.0',**ref('norms/tokens/blueheart.6.1.0.json'))
 save('norms/catalog.json',c)
 for p in ['norms/components/badge.1.0.0.md','norms/components/input.2.0.0.md','norms/tokens/blueheart.6.0.0.json']:(ROOT/p).unlink()
 # Make the recipe a selected projection before any native mutation.
 plan.update(contract=next(e for e in c['contracts']if e['id']=='BADGE-001'),token_set=next(e for e in c['token_sets']if e['current']))
 save(BASE+'build-plan.json',plan);save('consumption/badge/current-build-plan.json',plan);save('consumption/badge/token-minimum.json',read(BASE+'token-minimum.json'))
 return {'tokens':len(ts['tokens']),**plan['counts']}
if __name__=='__main__':print(json.dumps(adopt()))
